from flask import Flask, request, render_template_string, redirect, url_for
import os, secrets, sqlite3, json
from datetime import datetime
app=Flask(__name__)
app.secret_key=os.environ.get("SECRET_KEY",secrets.token_hex(32))
DB=os.path.join(os.path.dirname(__file__),"bookings.db")

AIRPORTS=[("ATL","Atlanta"),("AUS","Austin"),("BNA","Nashville"),("BOS","Boston"),("BWI","Baltimore/Washington"),("DAL","Dallas-Love Field"),("DEN","Denver"),("FLL","Fort Lauderdale"),("HOU","Houston Hobby"),("LAS","Las Vegas"),("LAX","Los Angeles"),("LGA","New York (LaGuardia)"),("MCO","Orlando"),("MDW","Chicago-Midway"),("MIA","Miami"),("MSY","New Orleans"),("OAK","Oakland"),("ONT","Ontario/LA"),("PHL","Philadelphia"),("PHX","Phoenix"),("SAN","San Diego"),("SEA","Seattle/Tacoma"),("SFO","San Francisco"),("SJC","San Jose, CA"),("SLC","Salt Lake City"),("SMF","Sacramento"),("SNA","Orange County/Santa Ana"),("STL","St. Louis"),("TPA","Tampa"),("TUS","Tucson"),("ABQ","Albuquerque"),("BOI","Boise"),("BUF","Buffalo/Niagara Falls"),("ELP","El Paso"),("HRL","Harlingen/South Padre Island"),("JAN","Jackson"),("LIT","Little Rock"),("OGG","Kahului"),("OKC","Oklahoma City"),("OMA","Omaha"),("PNS","Pensacola"),("RNO","Reno/Tahoe"),("RSW","Fort Myers"),("SAV","Savannah"),("TUL","Tulsa")]
AIRPORTS=[{"code":x,"city":y} for x,y in AIRPORTS]
BY={x["code"]:x for x in AIRPORTS}
ROUTES={"LAX":["LAS","PHX","DEN","SFO","OAK","SJC","SMF","SAN"],"LAS":["LAX","PHX","DEN","SFO","SAN","SLC","OAK"],"DEN":["LAS","PHX","DAL","MDW","AUS","LAX","SLC","SEA","SAN","MSY","MCO"],"PHX":["LAS","DEN","LAX","SAN","DAL","SLC","ABQ"],"DAL":["DEN","HOU","AUS","SAT","PHX","LAS","MSY","MCO","BNA","STL","OKC","TUL"],"HOU":["DAL","DEN","LAS","AUS","SAT","MSY","MCO","ATL","BNA","TPA"],"MDW":["DEN","LAS","DAL","MCO","BWI","BNA","STL","MSY","PHX"],"MCO":["DAL","DEN","MDW","BWI","ATL","FLL","MIA","TPA","BNA","PHL","HOU"],"ATL":["DAL","HOU","BWI","MCO","TPA","BNA","MSY","DEN"],"BWI":["ATL","MCO","MDW","BOS","PHL","DEN","TPA","FLL"],"BOS":["BWI","MDW","DEN","BNA"],"PHL":["BWI","MCO","ATL","DEN"],"BNA":["DAL","HOU","MCO","BWI","ATL","DEN","MDW","STL"],"TPA":["DAL","HOU","BWI","ATL","MCO","DEN","FLL","MSY"],"SAN":["LAX","LAS","PHX","DEN","OAK","SFO","SJC","SMF"],"SFO":["LAX","LAS","SAN","DEN","OAK","SJC","SEA"],"OAK":["LAX","LAS","SAN","SFO","SJC","SEA"],"SJC":["LAX","LAS","SAN","SFO","OAK","SEA"],"SMF":["LAX","LAS","SAN","DEN","SFO"],"SEA":["LAX","LAS","DEN","SFO","OAK","PHX"],"MSY":["DAL","HOU","DEN","MCO","BNA","ATL","TPA"],"STL":["DAL","DEN","BNA","MDW","MCO"],"SLC":["LAS","DEN","PHX","LAX"],"FLL":["MCO","TPA","BWI","HOU"],"MIA":["MCO"],"ONT":["PHX","LAS","DEN","SFO","SJC","OAK"],"SNA":["LAS","PHX","DEN","SFO","SJC"]}

